/** The Purchase Order's default print format on the old site (its DocType's default_print_format). */
export const DEFAULT_PO_PRINT_FORMAT = "PDF PO";

/** The formats in the old print view's order, Standard second. */
export const PO_FORMAT_NAMES: readonly string[] = [PO_PRINT_FORMATS[0].name, "Standard", ...PO_PRINT_FORMATS.slice(1).map((f) => f.name)];
